begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();p uuid:=gen_random_uuid();t uuid:=gen_random_uuid();job jsonb;retry jsonb;mail text:=b||'@example.invalid';
begin
 insert into auth.users(id,email,raw_user_meta_data) values(a,a||'@example.invalid','{}'),(b,mail,'{}'),(c,c||'@example.invalid','{}'),(d,d||'@example.invalid','{}');
 insert into public.sb_profiles(id,display_name) values(a,'Admin A'),(b,'Active member'),(c,'Other member'),(d,'Admin D');
 update public.sb_account_access set status='approved' where user_id in(a,b,c,d);
 insert into soundbar_private.sb_admins(user_id) values(a),(d);
 insert into soundbar_private.sb_admin_audit(actor,target,previous_status,new_status) values(a,b,'pending','approved');
 perform set_config('request.jwt.claim.sub',b::text,true);
 insert into public.sb_playlists(id,user_id,name) values(p,b,'Private playlist');
 insert into public.sb_tracks(id,user_id,playlist_id,name,sample_id) values(t,b,p,'Private track',(select id from public.sb_library_tracks where active limit 1));
 execute 'set local role authenticated';
 begin perform public.sb_prepare_account_deletion(c,c||'@example.invalid');raise exception 'Member deleted another member';exception when insufficient_privilege then null;end;
 begin perform public.sb_admin_accounts();raise exception 'Member listed accounts';exception when insufficient_privilege then null;end;
 begin perform public.sb_account_deletion_service('files',b,gen_random_uuid());raise exception 'Client called service';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 if not exists(select 1 from jsonb_array_elements(public.sb_admin_accounts()) x where x->>'user_id'=b::text and (x->>'can_delete')::boolean) then raise exception 'Approved account missing delete action';end if;
 begin perform public.sb_prepare_account_deletion(a,a||'@example.invalid');raise exception 'Admin deleted itself';exception when insufficient_privilege then null;end;
 begin perform public.sb_prepare_account_deletion(d,d||'@example.invalid');raise exception 'Admin deleted another admin';exception when insufficient_privilege then null;end;
 begin perform public.sb_prepare_account_deletion(b,'wrong@example.invalid');raise exception 'Wrong confirmation accepted';exception when invalid_parameter_value then null;end;
 if (select status from public.sb_account_access where user_id=b)<>'approved' then raise exception 'Wrong confirmation changed account';end if;
 job:=public.sb_prepare_account_deletion(b,mail);
 if job->>'status'<>'working' or (select status from public.sb_account_access where user_id=b)<>'blocked' then raise exception 'Active account not blocked';end if;
 begin perform public.sb_review_account(b,'approved');raise exception 'Deletion reactivated';exception when raise_exception then if sqlerrm='Deletion reactivated' then raise;end if;end;
 begin perform public.sb_prepare_account_deletion(b,mail);raise exception 'Concurrent deletion accepted';exception when lock_not_available then null;end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if soundbar_private.sb_is_approved() or (select count(*) from public.sb_playlists)<>0 then raise exception 'Old token still has account access';end if;
 execute 'reset role';
 begin perform public.sb_account_deletion_service('finish',b,(job->>'lease')::uuid,'{"status":"completed"}');raise exception 'Premature completion accepted';exception when raise_exception then if sqlerrm='Premature completion accepted' then raise;end if;end;
 perform public.sb_account_deletion_service('finish',b,(job->>'lease')::uuid,'{"status":"queued","phase":"files"}');
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';retry:=public.sb_prepare_account_deletion(b,mail);execute 'reset role';
 if retry->>'lease'=job->>'lease' then raise exception 'Lease not rotated';end if;
 begin perform public.sb_account_deletion_service('files',c,(retry->>'lease')::uuid);raise exception 'Wrong target accepted';exception when lock_not_available then null;end;
 delete from auth.users where id=b;
 perform public.sb_account_deletion_service('finish',b,(retry->>'lease')::uuid,'{"status":"completed","phase":"auth","http_status":200}');
 if exists(select 1 from public.sb_profiles where id=b) or exists(select 1 from public.sb_playlists where id=p) or exists(select 1 from public.sb_tracks where id=t) then raise exception 'Private account data remained';end if;
 if not exists(select 1 from public.sb_profiles where id=c) then raise exception 'Other account changed';end if;
 if not exists(select 1 from soundbar_private.sb_admin_audit where actor=a and target=b) then raise exception 'Moderation history lost';end if;
 if not exists(select 1 from soundbar_private.sb_account_deletions where user_id=b and status='completed' and email is null and display_name is null) then raise exception 'Personal deletion snapshot remained';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);execute 'set local role authenticated';if public.sb_account_state()->>'status'<>'deleted' then raise exception 'Deleted session appeared pending';end if;execute 'reset role';
 perform set_config('request.jwt.claim.sub',a::text,true);execute 'set local role authenticated';job:=public.sb_prepare_account_deletion(b,mail);if job->>'status'<>'completed' then raise exception 'Retry not idempotent';end if;execute 'reset role';
end$$;
rollback;
